import { Plugin } from "@opencode/plugin"
import * as v from "valibot"
import { AddressSession } from "../domain/my-pull-request.js"
import { nextFinding, questionHeader } from "../domain/review-draft.js"
import { ReviewedRecord } from "../domain/review-history.js"
import { everyPullRequest } from "../domain/review-queue.js"
import { qualifiedRepository } from "../domain/review-request.js"
import { repositorySnoozeKey, Snooze } from "../domain/snooze.js"
import { type PluginOptions, parseOptions } from "../shared/options.js"
import { type LocalReviews, ReviewQueue } from "../shared/rpc.js"
import { openReview, repositoryForDirectory } from "./github/repository.js"
import { type KeyedPersistence, KeyedStore } from "./keyed-store.js"
import { StorageLease } from "./queue-lease.js"
import { queueSource } from "./queue-source.js"
import { AddressSessions } from "./review/address.js"
import { decisionPrompt, EARLY_QUESTION, findingQuestionId, nextStep } from "./review/agent/instructions.js"
import { addSkillTools, waitForSkillSelection } from "./review/agent/skill-tools.js"
import { addReviewTools, hideReviewTools } from "./review/agent/tools.js"
import { defaultCacheDirectory, expandHome } from "./review/checkout.js"
import { DraftStore } from "./review/draft-store.js"
import { Findings } from "./review/findings.js"
import { rememberModel, reviewModels } from "./review/models.js"
import { ReviewSessions } from "./review/sessions.js"
import { watchSkillForms } from "./review/skill-events.js"
import { ReviewSkills } from "./review/skills.js"
import { summarize } from "./review/summary.js"
import { triage } from "./review/triage.js"
import { type PollerEvent, ReviewQueuePoller } from "./review-queue-poller.js"
import { pruneSnoozes } from "./snoozes.js"

// Cloning and fetching a large repository can take far longer than one GitHub API call.
const CHECKOUT_TIMEOUT_MS = 10 * 60_000
const SUMMARY_TIMEOUT_MS = 5 * 60_000
const DRAFT_PREFIX = "draft/"
const REVIEWED_PREFIX = "reviewed/"
const SNOOZE_PREFIX = "snooze/"
const COLLAPSED_PREFIX = "collapsed/"
const Collapsed = v.object({ version: v.literal(1), key: v.string() })
const ADDRESS_PREFIX = "address/"
// Missing a few renewals, such as while the machine sleeps, should not hand the lease over.
const LEASE_INTERVALS = 3

type Shared = {
  poller: ReviewQueuePoller
  drafts: DraftStore
  reviewed: KeyedStore<ReviewedRecord>
  snoozes: KeyedStore<Snooze>
  collapsed: KeyedStore<v.InferOutput<typeof Collapsed>>
  reviews: ReviewSessions
  addressing: AddressSessions
  findings: Findings
  skills: ReviewSkills
  refs: number
  started?: Promise<void>
}

let shared: Shared | undefined

type Json = Parameters<Plugin.Context["storage"]["set"]>[1]

function prefixed<T extends Json>(storage: Plugin.Context["storage"], prefix: string): KeyedPersistence<T> {
  return {
    get: (key) => storage.get(`${prefix}${key}`),
    list: async () => (await storage.scan({ prefix })).entries.map((entry) => entry.value),
    save: (key, value) => storage.set(`${prefix}${key}`, value),
    remove: (key) => storage.remove(`${prefix}${key}`),
  }
}

async function reported<T, E>(
  context: { error(type: "failed", message: string): E },
  run: () => Promise<T>,
): Promise<T | E> {
  try {
    return await run()
  } catch (error) {
    return context.error("failed", error instanceof Error ? error.message : String(error))
  }
}

async function localReviews(current: Shared): Promise<LocalReviews> {
  const [drafts, reviewed, snoozes, collapsed] = await Promise.all([
    current.drafts.list(),
    current.reviewed.list(),
    current.snoozes.list(),
    current.collapsed.list(),
  ])
  return { drafts, reviewed, snoozes, collapsed: collapsed.map((entry) => entry.key) }
}

function createShared(storage: Plugin.Context["storage"], options: PluginOptions): Shared {
  const lease = new StorageLease(
    {
      load: () => storage.get("lease"),
      save: (value) => storage.set("lease", value),
      remove: () => storage.remove("lease"),
    },
    LEASE_INTERVALS * options.intervalMs + options.timeoutMs,
  )
  const reviewed = new KeyedStore(ReviewedRecord, prefixed(storage, REVIEWED_PREFIX))
  const poller = new ReviewQueuePoller(
    queueSource(options, reviewed),
    {
      load: () => storage.get("baseline"),
      save: (value) => storage.set("baseline", value),
    },
    options,
    Date.now,
    lease,
  )
  const drafts = new DraftStore({
    get: (key) => storage.get(`${DRAFT_PREFIX}${key}`),
    list: async () => (await storage.scan({ prefix: DRAFT_PREFIX })).entries.map((entry) => entry.value),
    save: (draft) => storage.set(`${DRAFT_PREFIX}${draft.key}`, draft),
    remove: (key) => storage.remove(`${DRAFT_PREFIX}${key}`),
  })
  const snoozes = new KeyedStore(Snooze, prefixed(storage, SNOOZE_PREFIX))
  const cacheDirectory = options.cacheDirectory ? expandHome(options.cacheDirectory) : defaultCacheDirectory()
  const addressing = new AddressSessions(
    new KeyedStore(AddressSession, prefixed(storage, ADDRESS_PREFIX)),
    cacheDirectory,
  )
  const reviews = new ReviewSessions(drafts, reviewed, {
    cacheDirectory,
    guidelinesFile: options.reviewGuidelines && expandHome(options.reviewGuidelines),
    keepClones: options.keepClones,
    timeoutMs: options.timeoutMs,
  })
  poller.on((event) => {
    if (event.type === "fetched") {
      void reviews.pruneAfterRefresh(event.state, AbortSignal.timeout(options.timeoutMs))
      void pruneSnoozes(snoozes, everyPullRequest(event.state), Date.now()).catch(() => undefined)
      const authored = event.state.authored
      if (authored) {
        void addressing.prune(new Set(authored.map((item) => item.key))).catch(() => undefined)
      }
    }
  })
  return {
    poller,
    drafts,
    reviewed,
    snoozes,
    collapsed: new KeyedStore(Collapsed, prefixed(storage, COLLAPSED_PREFIX)),
    reviews,
    addressing,
    findings: new Findings(drafts, options.timeoutMs),
    skills: new ReviewSkills(drafts),
    refs: 0,
  }
}

export default Plugin.define({
  id: "github-review-queue",
  async setup(ctx) {
    const options = parseOptions(ctx.options)
    shared ??= createShared(ctx.storage, options)
    const current = shared
    current.refs += 1
    const timeout = (signal: AbortSignal, ms = options.timeoutMs) => AbortSignal.any([signal, AbortSignal.timeout(ms)])
    const queued = async (key: string) => {
      const item = everyPullRequest(await current.poller.latest()).find((candidate) => candidate.key === key)
      if (!item) {
        throw new Error("That pull request is no longer in the queue. Refresh and try again.")
      }
      return item
    }
    const panel = triage(current.findings, (input) => ctx.session.prompt(input))

    const registration = await ctx.rpc.register(ReviewQueue, {
      snapshot: async () => current.poller.snapshot(),
      refresh: () => current.poller.refresh(),
      repository: async (input, rpcContext) => {
        const found = await repositoryForDirectory(input.directory, timeout(rpcContext.signal))
        return { repository: found ? qualifiedRepository(found) : null }
      },
      open: (input, rpcContext) =>
        reported(rpcContext, async () => {
          await openReview(await queued(input.key), timeout(rpcContext.signal))
          return { opened: true }
        }),
      drafts: () => localReviews(current),
      models: () => reviewModels(ctx),
      skillPickers: async () => ({ requests: current.skills.requests() }),
      claimSkillPicker: async (input) => ({ claimed: current.skills.claim(input.id) }),
      failSkillPicker: async (input) => {
        current.skills.fail(input.id, input.message)
        return {}
      },
      answerSkillPicker: async (input) => {
        current.skills.answer(input.id, input.skills)
        return {}
      },
      startReview: (input, rpcContext) =>
        reported(rpcContext, async () => {
          const result = await current.reviews.start({
            item: await queued(input.key),
            directory: input.directory,
            clone: input.clone,
            mode: input.mode,
            model: input.model,
            sessions: ctx.session,
            signal: timeout(rpcContext.signal, CHECKOUT_TIMEOUT_MS),
          })
          if (result.status === "started" && input.model) {
            await rememberModel(ctx.storage, input.model)
          }
          return result
        }),
      addressReview: (input, rpcContext) =>
        reported(rpcContext, async () => {
          const result = await current.addressing.start({
            item: await queued(input.key),
            directory: input.directory,
            worktree: input.worktree,
            model: input.model,
            sessions: ctx.session,
            signal: timeout(rpcContext.signal, CHECKOUT_TIMEOUT_MS),
          })
          if (result.status === "started" && input.model) {
            await rememberModel(ctx.storage, input.model)
          }
          return result
        }),
      resetReview: (input, rpcContext) =>
        reported(rpcContext, async () => {
          await current.reviews.reset(input.key, timeout(rpcContext.signal))
          return {}
        }),
      postReview: (input, rpcContext) =>
        reported(rpcContext, () =>
          current.reviews.post(input.key, input.allowStale, timeout(rpcContext.signal), input.review),
        ),
      decideFinding: (input, rpcContext) => reported(rpcContext, () => panel.decide(input)),
      editFinding: (input, rpcContext) => reported(rpcContext, () => panel.edit(input)),
      askAboutFinding: (input, rpcContext) => reported(rpcContext, () => panel.ask(input)),
      addLineComments: (input, rpcContext) => reported(rpcContext, () => panel.addLineComments(input)),
      summarize: (input, rpcContext) =>
        reported(rpcContext, async () => {
          // Always the model the user picked: without one, the server falls back to a default they never chose.
          const generate = async (prompt: string, signal: AbortSignal) =>
            (await ctx.experimental.generate.text({ prompt, model: input.model }, { signal })).text
          return summarize(await queued(input.key), generate, timeout(rpcContext.signal, SUMMARY_TIMEOUT_MS))
        }),
      snooze: (input, rpcContext) =>
        reported(rpcContext, async () => {
          const item = await queued(input.key)
          await current.snoozes.put({
            version: 1,
            key: item.key,
            until: input.until,
            createdAt: new Date().toISOString(),
          })
          return localReviews(current)
        }),
      snoozeRepository: (input, rpcContext) =>
        reported(rpcContext, async () => {
          if (!(Date.parse(input.at) > Date.now())) {
            throw new Error("Pick a time in the future.")
          }
          const item = await queued(input.key)
          await current.snoozes.put({
            version: 1,
            key: repositorySnoozeKey(item),
            until: { kind: "time", at: input.at },
            createdAt: new Date().toISOString(),
          })
          return localReviews(current)
        }),
      collapse: (input, rpcContext) =>
        reported(rpcContext, async () => {
          const key = input.repository.toLowerCase()
          if (input.collapsed) {
            await current.collapsed.put({ version: 1, key })
          } else {
            await current.collapsed.remove(key)
          }
          return localReviews(current)
        }),
      wake: (input, rpcContext) =>
        reported(rpcContext, async () => {
          await current.snoozes.remove(input.key)
          return localReviews(current)
        }),
    })
    // The plugin's server context does not expose form.create; a connected UI creates the native form.
    // Its answer is observed here, not supplied by the model through another tool.
    const formEvents = new AbortController()
    void watchSkillForms(current.skills, ctx.event, formEvents.signal)
    const tools = await ctx.tool.transform((editor) => {
      addReviewTools(editor, current.findings)
      addSkillTools(
        editor,
        current.skills,
        ctx,
        {
          open: (request) => registration.events.emit("skillPicker", request),
          close: (request) => registration.events.emit("closeSkillPicker", request),
        },
        formEvents.signal,
      )
    })
    const reminder = await ctx.session.hook("context", async (event) => {
      const draft = await current.drafts.bySession(event.sessionID)
      if (!draft) {
        hideReviewTools(event.tools)
        return
      }
      waitForSkillSelection(event.tools, draft)
      const step = nextStep(draft)
      if (step) {
        event.system.push({ type: "text", text: step })
      }
    })
    // The finding this session was last prompted to ask about; cleared when the agent opens a question.
    const prompted = new Map<string, number>()
    const opened = await ctx.tool.hook("execute.before", (event) => {
      if (event.tool !== "question") {
        return
      }
      const id = findingQuestionId(event.input)
      // Models ignore the instruction to end the turn first, and the finding they wrote then stays hidden.
      if (id !== undefined && prompted.get(event.sessionID) !== id) {
        throw new Error(EARLY_QUESTION)
      }
      prompted.delete(event.sessionID)
    })
    const idle = await ctx.session.hook("experimental.idle", async (event) => {
      const draft = await current.drafts.bySession(event.sessionID)
      const finding = draft?.status === "ready" ? nextFinding(draft) : undefined
      if (!finding || prompted.get(event.sessionID) === finding.id) {
        return
      }
      prompted.set(event.sessionID, finding.id)
      await ctx.session.synthetic({
        sessionID: event.sessionID,
        text: decisionPrompt(finding),
        description: `Ask about ${questionHeader(finding.id)}`,
      })
    })

    const emit = (event: PollerEvent) => {
      switch (event.type) {
        case "state":
          void registration.events.emit("state", event.state)
          return
        case "discovered":
          void registration.events.emit("discovered", { item: event.item, eventID: event.eventID })
          return
        case "notice":
          void registration.events.emit("notice", { notice: event.notice, item: event.item, eventID: event.eventID })
          return
      }
    }
    const unsubscribe = current.poller.on(emit)
    const unsubscribeDrafts = current.drafts.on(
      () => void localReviews(current).then((local) => registration.events.emit("drafts", local)),
    )
    current.started ??= current.poller.start()
    await current.started

    return async () => {
      formEvents.abort()
      unsubscribe()
      unsubscribeDrafts()
      await tools.dispose()
      await reminder.dispose()
      await opened.dispose()
      await idle.dispose()
      await registration.dispose()
      current.refs -= 1
      if (current.refs === 0) {
        current.poller.stop()
        if (shared === current) {
          shared = undefined
        }
      }
    }
  },
})

import { ExitError, runProcess } from "../process.js"

class GitError extends Error {}

export async function runGit(directory: string, args: readonly string[], signal: AbortSignal): Promise<string> {
  try {
    const result = await runProcess("git", ["-C", directory, ...args], { signal })
    return result.stdout.trim()
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") {
      throw new GitError("Git was not found. Install it to review pull requests locally.")
    }
    if (error instanceof ExitError) {
      throw new GitError(`git ${args[0]} failed: ${error.message}`)
    }
    throw error
  }
}

import type { QueueError, QueueErrorKind } from "../../domain/review-queue.js"
import { GITHUB_COM, type RepositoryRef } from "../../domain/review-request.js"
import { type CommandResult, ExitError, type RunOptions, runProcess } from "../process.js"

export class GhError extends Error {
  constructor(readonly detail: QueueError) {
    super(detail.message)
  }
}

/** Naming github.com too keeps a `GH_HOST` in the user's environment from sending a call elsewhere. */
export const hostFlag = (host: string | undefined) => ["--hostname", host ?? GITHUB_COM]

/** `--repo` takes `HOST/OWNER/REPO`. */
export const repoName = (ref: RepositoryRef) => `${ref.host ?? GITHUB_COM}/${ref.repository}`

export async function runGh(args: readonly string[], options: RunOptions): Promise<CommandResult> {
  try {
    return await runProcess("gh", args, options)
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") {
      throw new GhError({
        kind: "missing-gh",
        message: "GitHub CLI (gh) was not found. Install it, then run `gh auth login`.",
      })
    }
    if (error instanceof ExitError) {
      throw classifyGhError(error.stderr || `gh exited with status ${String(error.code)}`)
    }
    throw error
  }
}

const KNOWN_FAILURES: readonly { kind: QueueErrorKind; patterns: readonly string[]; message: string }[] = [
  {
    kind: "authentication",
    patterns: ["authentication", "auth login", "bad credentials", "http 401"],
    message: "GitHub authentication failed. Run `gh auth status`, then `gh auth login` if needed.",
  },
  {
    kind: "rate-limit",
    patterns: ["rate limit", "secondary rate"],
    message: "GitHub rate limit reached. Polling will resume with backoff.",
  },
  {
    kind: "offline",
    patterns: [
      "could not resolve host",
      "network",
      "connection",
      "offline",
      "error connecting",
      "no such host",
      "dial tcp",
      "i/o timeout",
    ],
    message: "GitHub is unreachable. The last successful review queue is still shown.",
  },
  {
    kind: "unavailable",
    patterns: ["not found", "forbidden", "http 403"],
    message: "GitHub denied access to one or more repositories. Check your `gh` account and repository permissions.",
  },
]

function retryAfter(stderr: string): { retryAt?: string } {
  const seconds = stderr.match(/retry[- ]after[: ]+(\d+)/)?.[1]
  return seconds ? { retryAt: new Date(Date.now() + Number(seconds) * 1_000).toISOString() } : {}
}

export function classifyGhError(stderr: string): GhError {
  const text = stderr.trim()
  const lower = text.toLowerCase()
  const known = KNOWN_FAILURES.find((failure) => failure.patterns.some((pattern) => lower.includes(pattern)))
  if (!known) {
    return new GhError({
      kind: "unknown",
      message: text ? `GitHub request failed: ${text.split("\n")[0]}` : "GitHub request failed.",
    })
  }
  return new GhError({
    kind: known.kind,
    message: known.message,
    ...(known.kind === "rate-limit" ? retryAfter(lower) : {}),
  })
}
